{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Normalize nonpadding input embeddings by RMS before dropout to reduce GRU gate saturation. Keep padding zero and candidate embeddings unchanged. The generated predictor imports this same model class, so inference uses identical normalization without checkpoint changes.",
      "edits": [
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        emb = emb * torch.rsqrt(emb.square().mean(dim=-1, keepdim=True) + 1e-6)\n        return emb.masked_fill(seq.eq(0).unsqueeze(-1), 0.0)\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.input_embeddings(seq))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.input_embeddings(seq))"
        }
      ]
    }
  ],
  "change_summary": "Apply input-only RMS embedding normalization across all four category models in training and prediction, preserving the GRU, scoring, loss, optimizer, and routing."
}
